evaluate_vacancy_list:
'
            () => [...document.querySelectorAll('ul.collection.serp-list li')]
                    .map(v => {
                        const elem = v.querySelector('p.truncate.vacancy-name a')
                        const title = elem?.textContent || null;
                        const link = elem?.href || null;
                        const vacancy_id = link?.match(/\/vacancy\/([^/?#]+)/)?.[1] || null;

                        return { title, link, vacancy_id };
                    })
                    .filter(({ title, vacancy_id, link }) => title && vacancy_id && link)

evaluate_vacancy_page:
'
        ()=>{
            const job_title = (
                document.querySelector('h1')?.textContent?.trim() ||
                document.querySelector('main h1')?.textContent?.trim() ||
                ''
            );

            const job_text = (
                document.querySelector('article')?.textContent?.trim() ||
                document.querySelector('[class*="description"]')?.textContent?.trim() ||
                document.body?.textContent?.trim() ||
                ''
            );

            return {
                job_title,
                job_text,
            }
        }

evaluate_vacancy_list:
()=> {

const list = document.querySelectorAll('.vacancy-card');
const items = [...list].map(card=>{
    const link = card.querySelector('a')?.href || null;
    const vacancy_id = link?.match(/\/vacancies\/(\d+)/)?.[1] || null;
    const title = card.querySelector('a.vacancy-card__title-link').innerText
    return {
        link, vacancy_id,title
    }
})
return items;

}

evaluate_vacancy_page:
()=>{
const job_title = document.querySelector(".page-title__title");

const job_text = document.querySelector(".vacancy-description__text");
return {
job_title:job_title?.innerText ??'',
job_text:job_text?.innerText ?? ''
}
}

evaluate_pagination:
()=>{

const items = document.querySelectorAll('.with-pagination__pages a.with-pagination__page')

const list = [...items]
    .map(page=>page?.innerText || null)
    .filter(e=>e!=null);
return list;
}

